<!--vbase-->
<template>
  <div class="container no-padding back highlighted-back">
    <div class="secondary-c-text text-h6 q-pt-md q-pb-md">
      <q-btn flat rounded color="primary" to="/settings/document-types">
        <q-icon class="text-red-13" size="sm">
          <Icon icon="mdi:arrow-left" width="24" height="24" />
        </q-icon>
        <label
          style="
            vertical-align: middle;
            margin-left: 10px;
            font-size: 20px;
            cursor: pointer;
          "
          >{{ $t('back_to_list') }}</label
        >
      </q-btn>
    </div>
  </div>

  <div class="container text-color-grey">
    <div class="full-width">
      <q-list>
        <q-item
          v-for="(row, index) in document_type_templates"
          :key="index"
          class="q-mb-md q-pa-md bg-white grey-border"
        >
          <q-item-section avatar>
            <Icon icon="mdi:form-textbox" width="40" height="40" class="q-pr-sm q-pl-sm" />
          </q-item-section>
          <q-item-section class="text-weight-bold">
            <div>
              {{ row.title }} {{ row.doc_type_key }} {{ row.sub_doc_type_key }}
            </div>
          </q-item-section>
          <q-item-section avatar>
            <div class="row">
              <EditOrCreateBtn
                :doc_type_key="row.doc_type_key"
                :sub_doc_type_key="row.sub_doc_type_key"
              ></EditOrCreateBtn>
            </div>
          </q-item-section>
          <q-item-section avatar>
            <q-btn
              flat
              color="primary"
              class="no-padding-left-right"
              @click="
                deleteConfirm = true;
                selectedRowId = row.id;
                selectedRowIndex = Number(index);
              "
            >
              <Icon icon="mdi:delete" width="28" height="28" class="img-fluid mb-14" />
            </q-btn>
          </q-item-section>
        </q-item>
      </q-list>
    </div>
  </div>

  <q-dialog v-model="deleteConfirm" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('sure') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn
          flat
          :label="$t('cancel')"
          data-cy="cancel"
          color="primary"
          v-close-popup
        />
        <q-btn
          flat
          :label="$t('delete')"
          data-cy="delete-popup"
          color="primary"
          v-close-popup
          @click="deleteLayout()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { defineComponent, ref } from 'vue';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { formBuilderApiService } from 'src/services';
import { useFormBuilderStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import EditOrCreateBtn from 'src/pages/Settings/LayoutBuilder/EditOrCreateBtn.vue';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    
    Loader,
    EditOrCreateBtn,
  },
  data() {
    return {
      selectedRowId: ref(''),
      deleteConfirm: ref(false),
      selectedRowIndex: ref(0),
    };
  },
  mounted() {
    this.getTemplatesForDocuments();
  },

  methods: {
    async deleteLayout() {
      try {
        this.showLoading();
        const response =
          await formBuilderApiService.deleteDocumentLayoutTemplate(
            this.selectedRowId,
          );

        if (response.success === false) {
          notify.error(response.message);
          throw { message: response.message };
        }
        notify.success(this.$t('operation_sucessfull'));
        this.document_type_templates.splice(this.selectedRowIndex, 1);
        this.selectedRowId = '';
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { loading_templates, document_type_templates } =
      storeToRefs(form_builder_store);
    const { getTemplatesForDocuments } = form_builder_store;
    return {
      loading_templates,
      document_type_templates,
      getTemplatesForDocuments,
    };
  },
});
</script>

